import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  // Fetch candidates
  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(res.data);
      } catch (error) {
        console.error("Error fetching candidates:", error);
        alert("Failed to load candidates.");
      } finally {
        setLoading(false);
      }
    };

    fetchCandidates();
  }, []);

  // Handle Vote
  const handleVote = async (candidateId) => {
    if (submitting) return;

    const confirmVote = window.confirm(
      "Are you sure you want to vote for this candidate? This cannot be changed."
    );

    if (!confirmVote) return;

    try {
      setSubmitting(true);

      await axios.post(
        `${API_URL}/api/votes`,
        { candidateId },
        {
          headers: {
            Authorization: `Bearer ${auth?.token}`,
          },
        }
      );

      alert("✅ Vote cast successfully!");
    } catch (error) {
      console.error("Vote error:", error);
      alert("❌ Vote failed or you already voted.");
    } finally {
      setSubmitting(false);
    }
  };

  // Group candidates by position (optimized)
  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  // Loading state
  if (loading) {
    return (
      <div style={{ padding: 40, textAlign: "center" }}>
        <h2>Loading candidates...</h2>
      </div>
    );
  }

  // No candidates
  if (candidates.length === 0) {
    return (
      <div style={{ padding: 40, textAlign: "center" }}>
        <h2>No candidates available.</h2>
      </div>
    );
  }

  return (
    <div style={{ padding: 40, maxWidth: 1200, margin: "auto" }}>
      <h1 style={{ textAlign: "center", marginBottom: 40 }}>
        Student Election 2026
      </h1>

      {Object.entries(groupedCandidates).map(([position, list]) => (
        <div key={position} style={{ marginBottom: 50 }}>
          <h2 style={{ marginBottom: 20 }}>{position}</h2>

          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: 25,
            }}
          >
            {list.map((candidate) => (
              <div
                key={candidate._id}
                style={{
                  width: 300,
                  backgroundColor: "#ffffff",
                  borderRadius: 15,
                  padding: 20,
                  boxShadow: "0 8px 20px rgba(0,0,0,0.08)",
                  transition: "0.3s ease",
                }}
              >
                {/* Candidate Image */}
                {candidate.image && (
                  <img
                    src={`${API_URL}/${candidate.image}`}
                    alt={`${candidate.firstName} ${candidate.lastName}`}
                    style={{
                      width: "100%",
                      height: 200,
                      objectFit: "cover",
                      borderRadius: 10,
                      marginBottom: 15,
                    }}
                  />
                )}

                {/* Candidate Info */}
                <h3 style={{ marginBottom: 5 }}>
                  {candidate.firstName} {candidate.lastName}
                </h3>

                <p style={{ margin: "5px 0", fontSize: 14 }}>
                  🎓 {candidate.yearLevel} - {candidate.block}
                </p>

                <p
                  style={{
                    fontSize: 14,
                    marginTop: 10,
                    minHeight: 60,
                  }}
                >
                  {candidate.description}
                </p>

                {/* Vote Button */}
                <button
                  onClick={() => handleVote(candidate._id)}
                  disabled={submitting}
                  style={{
                    marginTop: 15,
                    padding: "10px",
                    width: "100%",
                    backgroundColor: submitting ? "#999" : "#6366f1",
                    color: "#fff",
                    border: "none",
                    borderRadius: 8,
                    fontWeight: "600",
                    cursor: submitting ? "not-allowed" : "pointer",
                  }}
                >
                  {submitting ? "Submitting..." : "Vote"}
                </button>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

export default VotingPage;
